      dsStatus.style.color='var(--ink3)';
      dsPower.disabled=true;dsStart.disabled=true;dsPairBtn.disabled=true;
      dsPower.className='chip';dsPower.textContent='不可用';
      dsStart.className='chip';dsStart.textContent='不可用';
      return;
