    dsStatus.textContent=ds.online?'已连接 · 你电脑的悬浮球在线':'未检测到在线的绑定电脑 · 可生成配对码绑定';
    dsStatus.style.color=ds.online?'#7EE7A7':'var(--ink3)';
    dsPower.disabled=false;dsStart.disabled=false;
