  dsPower.onclick=function(){ds.enabled=!ds.enabled;dsPaint();dsSend(ds.enabled?'桌面助手已开启':'桌面助手已关闭')};
  dsStart.onclick=function(){ds.autoStart=!ds.autoStart;dsPaint();dsSend()};
