    if(!t){toast('请先登录后再生成配对码','');return;}
    dsPairBtn.disabled=true;dsPairBtn.textContent='生成中…';
    fetch('/api/desktop/pair-code',{method:'POST',cache:'no-store',headers:{'Authorization':'Bearer '+t}})
      .then(function(r){return r.json()})
