function resetAIContext(){_aiMsgs=[]}

var _fabDragAt=0;
function clampFabPos(fab,x,y){
  var m=6,w=fab.offsetWidth||58,h=fab.offsetHeight||58;
  return {left:Math.max(m,Math.min(x,Math.max(m,innerWidth-w-m))),
          top:Math.max(m,Math.min(y,Math.max(m,innerHeight-h-m)))};
}
function applyFabPos(fab,pos){
  if(!pos||!isFinite(pos.left)||!isFinite(pos.top))return;
  var p=clampFabPos(fab,+pos.left,+pos.top);
  fab.style.right='auto';fab.style.bottom='auto';
  fab.style.left=p.left+'px';fab.style.top=p.top+'px';
}
function placeAgentPanel(fab,panel){
  if(!fab.style.left)return;
  var f=fab.getBoundingClientRect(),pw=panel.offsetWidth||360,ph=panel.offsetHeight||500,m=10,gap=10;
  var left=f.right-pw,top=f.top-ph-gap;
  if(top<m)top=(f.bottom+gap+ph<=innerHeight-m)?f.bottom+gap:m;
  left=Math.max(m,Math.min(left,innerWidth-pw-m));
  top=Math.max(m,Math.min(top,innerHeight-ph-m));
  panel.style.right='auto';panel.style.bottom='auto';
  panel.style.left=left+'px';panel.style.top=top+'px';
}
function attachFabDrag(fab,panel){
  var active=false,moved=false,sx=0,sy=0,ox=0,oy=0;
  function finish(e){
    if(!active)return;
    active=false;fab.classList.remove('dragging');
    if(moved){
      _fabDragAt=Date.now();
      storeSet('ivsim_fab_pos',{left:parseFloat(fab.style.left),top:parseFloat(fab.style.top)});
      if(panel.classList.contains('show'))placeAgentPanel(fab,panel);
    }
    if(e){try{fab.releasePointerCapture(e.pointerId)}catch(_){}}
  }
  fab.addEventListener('pointerdown',function(e){
    if(e.pointerType==='mouse'&&e.button!==0)return;
    var r=fab.getBoundingClientRect();
    sx=e.clientX;sy=e.clientY;ox=r.left;oy=r.top;moved=false;active=true;
    fab.classList.add('dragging');
    try{fab.setPointerCapture(e.pointerId)}catch(_){}
  });
  fab.addEventListener('pointermove',function(e){
    if(!active)return;
    var dx=e.clientX-sx,dy=e.clientY-sy;
    if(!moved&&Math.abs(dx)+Math.abs(dy)<5)return;
    moved=true;
    var p=clampFabPos(fab,ox+dx,oy+dy);
    fab.style.right='auto';fab.style.bottom='auto';
    fab.style.left=p.left+'px';fab.style.top=p.top+'px';
    e.preventDefault();
  });
  fab.addEventListener('pointerup',finish);
  fab.addEventListener('pointercancel',finish);
  window.addEventListener('resize',function(){
    if(fab.style.left)applyFabPos(fab,{left:parseFloat(fab.style.left),top:parseFloat(fab.style.top)});
    if(panel.classList.contains('show'))placeAgentPanel(fab,panel);
  });
}
/* Agent 工具名 → */
var AGENT_STEP_ICON={get_user_profile:'📊 查询训练数据',get_weak_points:'📉 分析薄弱点',search_questions:'🔍 检索题库'};
function mountAgent(){
  $$('.agent-fab,.agent-panel').forEach(function(n){n.remove()});
  var fab=document.createElement('button');fab.className='agent-fab';fab.title='面试小助手（可拖动到任意位置）';
  fab.innerHTML=ICONS.robot+'<span class="dot"></span>';
  function aiOn(){try{return typeof CLOUD!=='undefined'&&CLOUD.isConfigured()}catch(e){return false}}
  var headerStatus=aiOn()?'在线 · AI 已接入':'在线 · 模拟模式';
  var panel=document.createElement('div');panel.className='agent-panel';
  panel.innerHTML=
    '<div class="agent-head"><div class="a-av">🤖</div><div style="flex:1"><div class="a-nm">AI 面试助手</div><div class="a-st" id="agStatus">'+headerStatus+'</div></div><button class="m-x" id="agX">✕</button></div>'+
    '<div class="agent-body" id="agBody"></div>'+
    '<div class="agent-quick"><button data-q="怎么开始模拟面试？">怎么开始</button><button data-q="题库在哪里？">题库</button><button data-q="帮我制定一周训练计划">训练计划</button><button data-q="我的薄弱点在哪里？">薄弱点</button></div>'+
    '<div class="agent-input"><button id="agRag" title="答题模式（RAG 检索增强）：AI 先从题库检索真实题目再作答，并展示检索来源" aria-label="答题模式开关">📚</button><input id="agIn" placeholder="输入你的问题…（可问大模型）" maxlength="200" aria-label="输入你的问题"><button id="agSend" title="发送" aria-label="发送">'+ICONS.send+'</button></div>'+
    '<div class="agent-foot"><span id="agCtx" style="font-size:10.5px;color:var(--ink3)">对话记录: 0</span><button id="agReset" style="font-size:10.5px;color:var(--ink3);background:none;border:none;cursor:pointer">🔄 重置对话</button></div>';
  document.body.appendChild(fab);document.body.appendChild(panel);
  applyFabPos(fab,storeGet('ivsim_fab_pos',null));
  attachFabDrag(fab,panel);
  var body=panel.querySelector('#agBody'),input=panel.querySelector('#agIn'),
      statusEl=panel.querySelector('#agStatus'),ctxEl=panel.querySelector('#agCtx');
  function push(html,me){
    var d=document.createElement('div');d.className='msg '+(me?'me':'bot');d.innerHTML=html;body.appendChild(d);body.scrollTop=body.scrollHeight;return d;
  }
  var turns=0;
  /* RAG 答题模式开关 */
  var ragBtn=panel.querySelector('#agRag'),ragOn=false;
  function renderRag(){
    ragBtn.style.background=ragOn?'rgba(65,224,200,.16)':'none';
    ragBtn.style.border=ragOn?'1px solid rgba(65,224,200,.55)':'1px solid transparent';
    ragBtn.style.opacity=ragOn?'1':'.75';
    input.placeholder=ragOn?'输入题目，AI 结合题库检索作答…':'输入你的问题…（可问大模型）';
    ragBtn.title=ragOn?'答题模式已开启：AI 先检索题库真实题目再作答（点击关闭）':'答题模式（RAG 检索增强）：AI 先从题库检索真实题目再作答，并展示检索来源';
  }
  ragBtn.onclick=function(){ragOn=!ragOn;renderRag();toast(ragOn?'📚 答题模式（RAG）已开启':'已切回训练教练模式','ok')};
  renderRag();
  function updateStatus(){
    statusEl.textContent=aiOn()?'在线 · AI 已接入':'在线 · 模拟模式';
    ctxEl.textContent='对话记录: '+turns;
  }
  function answer(q){
    push(esc(q),true);
    turns++;
    fab.querySelector('.dot')&&fab.querySelector('.dot').remove();
    var loading=document.createElement('div');loading.className='msg bot';loading.innerHTML='<span class="typing"><i></i><i></i><i></i></span>';body.appendChild(loading);body.scrollTop=body.scrollHeight;

    if(aiOn()){
      var rule=agentReply(q);
      var sys=_sitePrompt();
      var ruleRef=!rule.fallback?('\n（内部参考：此问题在本站的官方话术——'+rule.r.replace(/<[^>]+>/g,' ')+'）'):'';
      _aiMsgs=_aiMsgs.concat({role:'user',content:q});
      function showText(t,steps,sources){
        var html='';
        if(steps&&steps.length) html+='<div style="font-size:11px;color:#8fb7ff;background:rgba(108,140,255,.08);border:1px solid rgba(108,140,255,.25);border-radius:8px;padding:4px 8px;margin-bottom:6px">🛠 Agent 工具调用：'+esc(steps.map(function(s){return AGENT_STEP_ICON[s]||s}).join(' → '))+'</div>';
        if(sources&&sources.length) html+='<div style="font-size:11px;color:#2dd4bf;background:rgba(65,224,200,.08);border:1px solid rgba(65,224,200,.3);border-radius:8px;padding:5px 8px;margin-bottom:6px">📚 RAG 检索到 '+sources.length+' 道相关题：<br>'+sources.map(function(s,i){return '<span style="opacity:.85">'+(i+1)+'. '+esc(s.q.slice(0,32))+(s.q.length>32?'…':'')+'</span>'}).join('<br>')+'</div>';
        html+=mdLite(t);
        push(html);
        updateStatus();
      }
      var localFall=function(){
        loading.remove();
        var r=agentReply(q);
        push('⚠️ AI 暂时不可用，已切换到本地模拟回答：<br><br>'+r.r);
        updateStatus();
      };
      /* RAG 答题模式 */
      if(ragOn&&typeof CLOUD.aiAsk==='function'){
        loading.innerHTML='<div style="font-size:11.5px;color:#2dd4bf">📚 正在检索题库…</div>';
        CLOUD.aiAsk(q,_aiMsgs.slice(-4)).then(function(res){
          loading.remove();
          _aiMsgs=_aiMsgs.concat({role:'assistant',content:res.text});
          showText(res.text,null,res.sources);
        })['catch'](function(){
          /* RAG 失败回落训练教练 Agent */
          askAgent();
        });
        return;
      }
      function askAgent(){
        if(typeof CLOUD.aiAgentStream==='function'){
                    var liveTxt='',stepsSeen=[];
          function stepHtml(){
            if(!stepsSeen.length)return '';
            return '<div style="font-size:11px;color:#8fb7ff;background:rgba(108,140,255,.08);border:1px solid rgba(108,140,255,.25);border-radius:8px;padding:4px 8px;margin-bottom:6px">🛠 '+esc(stepsSeen.map(function(s){return AGENT_STEP_ICON[s]||s}).join(' → '))+'</div>';
          }
          function showThink(label){
            loading.innerHTML=stepHtml()+'<div style="font-size:11.5px;color:#8fb7ff">'+esc(label||'🤔 正在思考…')+'</div><span class="typing"><i></i><i></i><i></i></span>';
            body.scrollTop=body.scrollHeight;
          }
          function showStream(full){
            /* 流式期间先剥掉末尾未闭合的 */
            loading.innerHTML=stepHtml()+'<div style="font-size:var(--fs-sm);line-height:1.75;word-break:break-word">'+mdLite(String(full).replace(/\*\*[^*\n]*$/,''))+'<span style="opacity:.45">▍</span></div>';
            body.scrollTop=body.scrollHeight;
          }
          showThink('🤔 正在思考…');
          CLOUD.aiAgentStream(_aiMsgs.slice(-10),
            function(label,tool){
              if(tool&&stepsSeen.indexOf(tool)<0)stepsSeen.push(tool);
              if(liveTxt)showStream(liveTxt);else showThink(label);
            },
            function(delta,full){
              if(delta===null){liveTxt='';showThink();return}
              liveTxt=full;showStream(full);
            },
            function(){ if(!liveTxt)showThink(); }
          ).then(function(res){
            loading.remove();
            _aiMsgs=_aiMsgs.concat({role:'assistant',content:res.text});
            showText(res.text,res.steps);
          })['catch'](function(){
            CLOUD.aiText(sys+ruleRef,_aiMsgs.slice(-10)).then(function(t){
              loading.remove();
              _aiMsgs=_aiMsgs.concat({role:'assistant',content:t});
              showText(t);
            })['catch'](localFall);
          });
          return;
        }
        if(typeof CLOUD.aiAgent==='function'){
          CLOUD.aiAgent(_aiMsgs.slice(-10)).then(function(res){
            loading.remove();
            _aiMsgs=_aiMsgs.concat({role:'assistant',content:res.text});
            showText(res.text,res.steps);
          })['catch'](function(){
            CLOUD.aiText(sys+ruleRef,_aiMsgs.slice(-10)).then(function(t){
              loading.remove();
              _aiMsgs=_aiMsgs.concat({role:'assistant',content:t});
              showText(t);
            })['catch'](localFall);
          });
          return;
        }
        CLOUD.aiText(sys+ruleRef,_aiMsgs.slice(-10)).then(function(t){
          loading.remove();
          _aiMsgs=_aiMsgs.concat({role:'assistant',content:t});
          showText(t);
        })['catch'](localFall);
      }
      askAgent();
      return;
    }
    /* 模拟模式：本地关键词匹配 */
    setTimeout(function(){
      loading.remove();
      var r=agentReply(q);
      var d=push(r.r);
      if(r.acts){
        var actHtml='<div class="m-act">'+r.acts.map(function(a,i){return '<button data-i="'+i+'">'+esc(a.t)+'</button>'}).join('')+'</div>';
        d.insertAdjacentHTML('beforeend',actHtml);
        $$('.m-act button[data-i]',d).forEach(function(b){b.onclick=function(){var a=r.acts[+b.dataset.i];if(a.go)location.href=a.go;else if(a.fb){panel.classList.remove('show');openFeedback()}else if(a.act==='checkin'){panel.classList.remove('show');checkIn();showCheckinPanel()}else if(a.act==='ach'){panel.classList.remove('show');openAchievements()}}});
      }
      updateStatus();
    },400);
  }
  push('嗨～我是 AI 训练教练 🤖 会查你的真实训练数据和题库来回答：可以让我分析薄弱点、出题、制定训练计划，也能聊面试技巧。');
  updateStatus();
  fab.onclick=function(){
    if(Date.now()-_fabDragAt<350)return;
    var willShow=!panel.classList.contains('show');
    panel.classList.toggle('show',willShow);
    if(willShow)placeAgentPanel(fab,panel);
    var d=fab.querySelector('.dot');if(d)d.remove();
  };
  panel.querySelector('#agX').onclick=function(){panel.classList.remove('show')};
  panel.querySelector('#agSend').onclick=function(){var v=input.value.trim();if(!v)return;input.value='';answer(v)};
  panel.querySelector('#agReset').onclick=function(){
    body.innerHTML='';turns=0;resetAIContext();updateStatus();
    push('嗨～我是 AI 训练教练 🤖 会查你的真实训练数据和题库来回答：可以让我分析薄弱点、出题、制定训练计划，也能聊面试技巧。');
    toast('对话历史已重置','ok');
  };
  input.addEventListener('keydown',function(e){if(e.key==='Enter'){var v=input.value.trim();if(!v)return;input.value='';answer(v)}});
  $$('.agent-quick button',panel).forEach(function(b){b.onclick=function(){answer(b.dataset.q)}});
}

function checkIn(){
  var today=new Date().toDateString();
  var data=userGet('checkin',{days:0,total:0,last:'',history:[]});
  if(data.last===today){toast('今天已经签过啦，明天再来吧','warn');return {done:true,data:data,streak:calcStreak(data.history)}}
  var hist=data.history.slice();
  hist.push(today);
  data.history=hist;
  data.last=today;
  data.total=data.total+1;
  data.days=calcStreak(hist);
  userSet('checkin',data);
  try{syncProfile()}catch(e){}
  toast('签到成功！连续 '+data.days+' 天，累计 '+data.total+' 天','ok');
  tryUnlockAll();
  playSound('checkin');
  return {done:false,data:data,streak:data.days};
}
function calcStreak(hist){
  var set={};hist.forEach(function(d){set[d]=1});
  var c=0,t=new Date();
  while(set[t.toDateString()]){c++;t.setDate(t.getDate()-1)}
  return c;
}
function getCheckInfo(){return userGet('checkin',{days:0,total:0,last:'',history:[]})}

